"""Escribe la documentacion didactica del proyecto en docs/."""
import os, base64
A = {
  'docs/GUIA_DIDACTICA.md': "",
  'docs/METODOLOGIA_MODELO.md': "",
  'docs/CODIGO_FUENTE.md': "",
  'docs/INTERFAZ_index_html.md': "",
}
os.makedirs("docs", exist_ok=True)
for ruta, b in A.items():
    d = base64.b64decode(b)
    open(ruta, "wb").write(d)
    print("escrito: %-40s %7d bytes" % (ruta, len(d)))
print("\nListo. %d documentos en docs/" % len(A))